import java.util.concurrent.RecursiveTask;
import java.util.concurrent.ForkJoinPool;

public class binarytrees {
    static final int MIN_DEPTH = 4;

    static int bottomUpTree(int depth) {
        if (depth == 0) return 1;
        return 1 + bottomUpTree(depth - 1) + bottomUpTree(depth - 1);
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);
        int maxDepth = Math.max(MIN_DEPTH + 2, n);
        int stretchDepth = maxDepth + 1;

        int check = bottomUpTree(stretchDepth);
        System.out.println("stretch tree of depth " + stretchDepth + "\t check: " + check);

        int longLivedCheck = bottomUpTree(maxDepth);

        StringBuilder sb = new StringBuilder();
        for (int depth = MIN_DEPTH; depth <= maxDepth; depth += 2) {
            int iterations = 1 << (maxDepth - depth + MIN_DEPTH);
            long sum = 0;
            for (int i = 0; i < iterations; i++) {
                sum += bottomUpTree(depth);
            }
            sb.append(iterations).append("\t trees of depth ").append(depth)
              .append("\t check: ").append(sum).append("\n");
        }
        System.out.print(sb);

        System.out.println("long lived tree of depth " + maxDepth + "\t check: " + longLivedCheck);
    }
}
