import java.io.OutputStream;
import java.io.IOException;

public class fasta {
    static final int LINE = 60;
    static int seed = 42;
    static final int IM = 139968;
    static final int IA = 3877;
    static final int IC = 29573;

    static byte[] buf = new byte[1 << 16];
    static int bufPos = 0;
    static OutputStream out;

    static void flush() throws IOException {
        if (bufPos > 0) { out.write(buf, 0, bufPos); bufPos = 0; }
    }

    static void write(byte b) throws IOException {
        if (bufPos == buf.length) flush();
        buf[bufPos++] = b;
    }

    static void writeStr(String s) throws IOException {
        byte[] b = s.getBytes();
        for (byte x : b) write(x);
    }

    static double nextRandom() {
        seed = (seed * IA + IC) % IM;
        return (double) seed / IM;
    }

    static void repeatFasta(byte[] alu, int n) throws IOException {
        int aluLen = alu.length;
        int idx = 0;
        int col = 0;
        for (int i = 0; i < n; i++) {
            write(alu[idx]);
            idx++;
            if (idx == aluLen) idx = 0;
            col++;
            if (col == LINE) { write((byte)'\n'); col = 0; }
        }
        if (col > 0) write((byte)'\n');
    }

    static void randomFasta(byte[] symbols, double[] probs, int n) throws IOException {
        int m = symbols.length;
        double[] cum = new double[m];
        double c = 0;
        for (int i = 0; i < m; i++) { c += probs[i]; cum[i] = c; }
        cum[m-1] = 1.0;

        int col = 0;
        for (int i = 0; i < n; i++) {
            double r = nextRandom();
            int j = 0;
            while (cum[j] <= r) j++;
            write(symbols[j]);
            col++;
            if (col == LINE) { write((byte)'\n'); col = 0; }
        }
        if (col > 0) write((byte)'\n');
    }

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(args[0]);
        out = System.out;

        String alu =
            "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
            "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
            "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
            "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
            "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

        byte[] iubSym = {'a','c','g','t','B','D','H','K','M','N','R','S','V','W','Y'};
        double[] iubProb = {0.27,0.12,0.12,0.27,0.02,0.02,0.02,0.02,0.02,0.02,0.02,0.02,0.02,0.02,0.02};

        byte[] homoSym = {'a','c','g','t'};
        double[] homoProb = {0.3029549426680,0.1979883004921,0.1975473066391,0.3015094502008};

        writeStr(">ONE Homo sapiens alu\n");
        repeatFasta(alu.getBytes(), 2 * n);

        writeStr(">TWO IUB ambiguity codes\n");
        randomFasta(iubSym, iubProb, 3 * n);

        writeStr(">THREE Homo sapiens frequency\n");
        randomFasta(homoSym, homoProb, 5 * n);

        flush();
        out.flush();
