public class mandelbrot {
    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);
        int width = n, height = n;
        int lineBytes = (width + 7) / 8;
        byte[] data = new byte[lineBytes * height];

        double inv = 2.0 / n;

        int numThreads = Runtime.getRuntime().availableProcessors();
        Thread[] threads = new Thread[numThreads];
        AtomicInteger rowCounter = new AtomicInteger(0);

        for (int t = 0; t < numThreads; t++) {
            threads[t] = new Thread(() -> {
                int y;
                while ((y = rowCounter.getAndIncrement()) < height) {
                    int rowOff = y * lineBytes;
                    double ci = y * inv - 1.0;
                    int xbyte = 0;
                    int bits = 0;
                    int bitCount = 0;
                    for (int x = 0; x < width; x++) {
                        double cr = x * inv - 1.5;
                        double zr = 0.0, zi = 0.0;
                        double zr2 = 0.0, zi2 = 0.0;
                        int i = 0;
                        boolean inside = true;
                        for (; i < 50; i++) {
                            zi = 2.0 * zr * zi + ci;
                            zr = zr2 - zi2 + cr;
                            zr2 = zr * zr;
                            zi2 = zi * zi;
                            if (zr2 + zi2 > 4.0) { inside = false; break; }
                        }
                        bits = (bits << 1) | (inside ? 1 : 0);
                        bitCount++;
                        if (bitCount == 8) {
                            data[rowOff + xbyte] = (byte) bits;
                            xbyte++;
                            bits = 0;
                            bitCount = 0;
                        }
                    }
                    if (bitCount != 0) {
                        bits <<= (8 - bitCount);
                        data[rowOff + xbyte] = (byte) bits;
                    }
                }
            });
            threads[t].start();
        }
        for (Thread th : threads) th.join();

        OutputStream out = new BufferedOutputStream(System.out);
        out.write(("P4\n" + width + " " + height + "\n").getBytes("US-ASCII"));
        out.write(data);
        out.flush();
    }
}
