            vy[i] = vyi;
            vz[i] = vzi;
        }
        for (int i = 0; i < N_BODIES; i++) {
            x[i] += dt * vx[i];
            y[i] += dt * vy[i];
            z[i] += dt * vz[i];
        }
    }

