        int n = Integer.parseInt(args[0]);
        init();
        offsetMomentum();
        System.out.printf("%.9f%n", energy());
        for (int i = 0; i < n; i++) {
            advance(0.01);
        }
        System.out.printf("%.9f%n", energy());
    }
